CREATE TABLE "VideoLiveSession" ("id" TEXT NOT NULL,"publicId" TEXT NOT NULL,"hostId" TEXT NOT NULL,"title" TEXT NOT NULL,"coverUrl" TEXT,"status" TEXT NOT NULL DEFAULT 'LIVE',"hostAway" BOOLEAN NOT NULL DEFAULT false,"viewerCount" INTEGER NOT NULL DEFAULT 0,"peakViewers" INTEGER NOT NULL DEFAULT 0,"likeCount" INTEGER NOT NULL DEFAULT 0,"giftIncome" BIGINT NOT NULL DEFAULT 0,"revision" INTEGER NOT NULL DEFAULT 0,"startedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"endedAt" TIMESTAMP(3),CONSTRAINT "VideoLiveSession_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "VideoLiveSession_publicId_key" ON "VideoLiveSession"("publicId");CREATE INDEX "VideoLiveSession_status_startedAt_idx" ON "VideoLiveSession"("status","startedAt");CREATE INDEX "VideoLiveSession_hostId_startedAt_idx" ON "VideoLiveSession"("hostId","startedAt");
CREATE TABLE "VideoLiveViewer" ("sessionId" TEXT NOT NULL,"userId" TEXT NOT NULL,"active" BOOLEAN NOT NULL DEFAULT true,"joinedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"lastSeenAt" TIMESTAMP(3) NOT NULL,CONSTRAINT "VideoLiveViewer_pkey" PRIMARY KEY ("sessionId","userId"));CREATE INDEX "VideoLiveViewer_sessionId_active_idx" ON "VideoLiveViewer"("sessionId","active");
CREATE TABLE "VideoLiveGuestRequest" ("id" TEXT NOT NULL,"sessionId" TEXT NOT NULL,"userId" TEXT NOT NULL,"status" TEXT NOT NULL DEFAULT 'PENDING',"slot" INTEGER,"requestedAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP,"expiresAt" TIMESTAMP(3) NOT NULL,"respondedAt" TIMESTAMP(3),CONSTRAINT "VideoLiveGuestRequest_pkey" PRIMARY KEY ("id"));CREATE INDEX "VideoLiveGuestRequest_sessionId_status_requestedAt_idx" ON "VideoLiveGuestRequest"("sessionId","status","requestedAt");CREATE UNIQUE INDEX "VideoLiveGuestRequest_sessionId_userId_status_key" ON "VideoLiveGuestRequest"("sessionId","userId","status");
ALTER TABLE "VideoLiveSession" ADD CONSTRAINT "VideoLiveSession_hostId_fkey" FOREIGN KEY ("hostId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "VideoLiveViewer" ADD CONSTRAINT "VideoLiveViewer_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "VideoLiveSession"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "VideoLiveViewer" ADD CONSTRAINT "VideoLiveViewer_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "VideoLiveGuestRequest" ADD CONSTRAINT "VideoLiveGuestRequest_sessionId_fkey" FOREIGN KEY ("sessionId") REFERENCES "VideoLiveSession"("id") ON DELETE CASCADE ON UPDATE CASCADE;ALTER TABLE "VideoLiveGuestRequest" ADD CONSTRAINT "VideoLiveGuestRequest_userId_fkey" FOREIGN KEY ("userId") REFERENCES "User"("id") ON DELETE CASCADE ON UPDATE CASCADE;
